import React, { useEffect, useRef, useState } from "react";
import FileUploadIcon from "@mui/icons-material/FileUpload";
import http, { uploadImage } from "../../services/utility";
import { apisPath, paths } from "../../utils/path";
import { useNavigate } from "react-router-dom";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { useDispatch } from "react-redux";
import {
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  Button,
} from "@mui/material";

export default function Categories() {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const newCategoryRef = useRef(null);
  const [categoryName, setCategoryName] = useState("");
  const [categoryImage, setCategoryImage] = useState(null);
  const [cardData, setCardData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [id, setId] = useState(null);

  // Modal state
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [categoryToDelete, setCategoryToDelete] = useState(null);

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    setLoading(true);
    await http
      .get(apisPath?.admin?.allCategories)
      .then(async (res) => {
        setCardData(res?.data?.categories);
        setLoading(false);
      })
      .catch((err) => {
        console.log(err);
        setLoading(false);
      });
  };

  const openDeleteModal = (category) => {
    setCategoryToDelete(category);
    setDeleteModalOpen(true);
  };

  const handleCloseDeleteModal = () => {
    setDeleteModalOpen(false);
    setCategoryToDelete(null);
  };

  const confirmDelete = async () => {
    if (!categoryToDelete) return;

    await http
      .delete(`${apisPath?.admin?.categories}?id=${categoryToDelete.id}`)
      .then(async (res) => {
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
        handleCloseDeleteModal();
      })
      .catch((err) => {
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
        handleCloseDeleteModal();
      });
  };


  return (
    <div className="categories">
      <div className="categories__heading">
        <h3 className="categories__heading_text page_heading">Categories</h3>
        <button
          className="button-red"
          onClick={() =>
            navigate(
              `/${paths?.front?.user?.products}/${paths?.front?.user?.add_new_category}`
            )
          }
        >
          Add New Category
        </button>
      </div>
      <div className="categories__content">
        <div className="categories__content__categories_list">
          <div className="categories__content__categories_list__content">
            {loading ? (
              <div className="loading_progress">
                <div className="loading_spinner"></div>
                <p>Loading categories...</p>
              </div>
            ) : cardData.length > 0 ? (
              cardData?.map((data, index) => {
                return (
                  <CategoryCard
                    key={index}
                    data={data}
                    image={data?.imageOn}
                    name={data?.name}
                    deleteData={() => openDeleteModal(data)}
                    id={data?.id}
                  />
                );
              })
            ) : (
              <div className="no_data_found">No Data Found</div>
            )}
          </div>
        </div>
      </div>

      {/* Delete Confirmation Modal */}
      <Dialog
        open={deleteModalOpen}
        onClose={handleCloseDeleteModal}
        aria-labelledby="delete-dialog-title"
        aria-describedby="delete-dialog-description"
        className="categories__delete_modal"
        disablePortal={false}
        container={document.body}
        style={{
          position: 'fixed',
          zIndex: 9999999,
        }}
        BackdropProps={{
          style: {
            position: 'fixed',
            zIndex: 9999998,
          },
        }}
      >
        <DialogTitle id="delete-dialog-title">Delete Category</DialogTitle>
        <DialogContent>
          <div className="delete-icon-container">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M19 7L18.1327 19.1425C18.0579 20.1891 17.187 21 16.1378 21H7.86224C6.81296 21 5.94208 20.1891 5.86732 19.1425L5 7M10 11V17M14 11V17M15 7V4C15 3.44772 14.5523 3 14 3H10C9.44772 3 9 3.44772 9 4V7M4 7H20" stroke="#dc2626" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </div>
          <DialogContentText id="delete-dialog-description">
            Are you sure you want to delete <strong>"{categoryToDelete?.name}"</strong>?
          </DialogContentText>
          <DialogContentText>
            This action cannot be undone. All associated data will be permanently removed.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDeleteModal} variant="outlined" className="cancel-btn">
            Cancel
          </Button>
          <Button onClick={confirmDelete} variant="contained" className="delete-btn">
            Delete Category
          </Button>
        </DialogActions>
      </Dialog>
    </div>
  );
}

const CategoryCard = ({ image, name, deleteData, id, data }) => {
  const navigate = useNavigate();

  return (
    <div className="categories_list_card">
      <div className="categories_list_card__content">
        <img src={image} alt={name} />
      </div>
      <div style={{ display: 'flex', gap: '10px', flexDirection: 'column' }}>
        <button
          className="button-border-red"
          onClick={() => {
            navigate(
              `/${paths?.front?.user?.products}/${paths?.front?.user?.add_new_category}`,
              {
                state: { data: data },
              }
            );
          }}
        >
          Edit
        </button>
        <button className="button-red" onClick={deleteData}>
          Delete
        </button>
      </div>
    </div>
  );
};
